/** Typed view of the bundled study data (generated by scripts/build_console_data.py; the console never recomputes it). */
import raw from "./generated/study.json";

export type RuntimeRow = { id: string; label: string; pass_rate: number; ci: number[]; n_runs: number; claim_precision: number | null;
  cost_usd: number | null; latency_s: number; cache_share?: number | null };
type Extras = {
  runtime?: { configs: RuntimeRow[]; deltas: Array<{ contrast: string; delta: number; ci95: number[]; significant: boolean }>; note: string;
    headline: { api_c_28: number; claude_code_c_28: number } };
  redteam?: { runs: number; pass_rate: number; tasks: Array<{ id: string; category: string; passes: boolean[]; failed_checks: string[] }>; note: string };
};

export const study = raw as typeof raw & Extras;
export const pct = (n: number) => `${Math.round(n * 1000) / 10}%`;
export const pts = (n: number) => `${n >= 0 ? "+" : ""}${Math.round(n * 1000) / 10}`;
export const money = (n: number | null | undefined) => (n == null ? "—" : n === 0 ? "$0" : `$${n.toFixed(4)}`);
